package pro.xiangyu.cashierhelper.network

import java.util.Base64
import java.util.concurrent.TimeUnit
import kotlinx.coroutines.CoroutineStart
import kotlinx.coroutines.cancelAndJoin
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withTimeout
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import okhttp3.OkHttpClient
import okhttp3.mockwebserver.MockResponse
import okhttp3.mockwebserver.MockWebServer
import okhttp3.mockwebserver.SocketPolicy
import okhttp3.tls.HandshakeCertificates
import okhttp3.tls.HeldCertificate
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test
import pro.xiangyu.cashierhelper.config.AppConfig

class CashierApiClientTest {
    private lateinit var server: MockWebServer
    private lateinit var httpsClient: OkHttpClient

    @Before
    fun setUp() {
        // The client only accepts HTTPS, so the fake server must speak TLS and
        // the test client must trust its certificate.
        val heldCertificate = HeldCertificate.Builder()
            .commonName("localhost")
            .addSubjectAlternativeName("localhost")
            .build()
        val serverCertificates = HandshakeCertificates.Builder()
            .heldCertificate(heldCertificate)
            .build()
        val clientCertificates = HandshakeCertificates.Builder()
            .addTrustedCertificate(heldCertificate.certificate)
            .build()

        httpsClient = OkHttpClient.Builder()
            .sslSocketFactory(clientCertificates.sslSocketFactory(), clientCertificates.trustManager)
            .build()
        server = MockWebServer()
        server.useHttps(serverCertificates.sslSocketFactory(), false)
        server.start()
    }

    @After
    fun tearDown() {
        server.shutdown()
    }

    @Test
    fun `sends only minimal cashier payload and accepts processing response`() = runBlocking {
        server.enqueue(
            MockResponse()
                .setResponseCode(201)
                .setBody("""{"sourceDocumentId":"a","revisionState":"processing","status":"processing"}"""),
        )
        val jpeg = byteArrayOf(1, 2, 3, 4)

        val result = CashierApiClient(httpsClient).upload(config(), jpeg, IDEMPOTENCY_KEY)

        assertEquals(UploadResult.Accepted("a"), result)
        val request = server.takeRequest()
        assertEquals("POST", request.method)
        assertEquals("/api/v1/source-documents", request.path)
        assertEquals("Bearer secret-key", request.getHeader("Authorization"))
        assertTrue(request.getHeader("Content-Type")!!.startsWith("application/json"))
        // The key is supplied by the caller and forwarded verbatim so a retry
        // reuses the original key instead of minting a new one.
        assertEquals(IDEMPOTENCY_KEY, request.getHeader("Idempotency-Key"))

        val json = Json.parseToJsonElement(request.body.readUtf8()).jsonObject
        assertEquals(setOf("images"), json.keys)
        val image = json.getValue("images").jsonArray.single().jsonObject
        assertEquals(setOf("data", "mimeType"), image.keys)
        assertEquals(Base64.getEncoder().encodeToString(jpeg), image.getValue("data").jsonPrimitive.content)
        assertEquals("image/jpeg", image.getValue("mimeType").jsonPrimitive.content)
        assertFalse("entryDate" in json)
    }

    @Test
    fun `requires exact success contract`() = runBlocking {
        listOf(
            """{"revisionState":"processing"}""",
            """{"sourceDocumentId":"a","revisionState":"queued"}""",
            "not-json",
        ).forEach { body ->
            server.enqueue(MockResponse().setResponseCode(201).setBody(body))
            assertEquals(
                UploadResult.Failed(UploadFailure.INVALID_RESPONSE),
                CashierApiClient(httpsClient).upload(config(), byteArrayOf(1), IDEMPOTENCY_KEY),
            )
        }
    }

    @Test
    fun `parses all source document states and completed items`() = runBlocking {
        val responses = listOf(
            """{"status":"processing","result":null,"error":null}""" to
                StatusQueryResult.Status(SourceDocumentStatus.Processing),
            """{"status":"completed","result":{"title":"午餐","total":"10.20","totalCurrency":"CNY","entries":[{"name":"面条","description":null,"amount":"10.20","currency":"CNY","category":"餐饮"}]},"error":null}""" to
                StatusQueryResult.Status(
                    SourceDocumentStatus.Completed(
                        listOf(ConsumptionItem("10.20".toBigDecimal(), "CNY", "餐饮")),
                    ),
                ),
            """{"status":"invalid","result":null,"error":{"code":"VALIDATION_FAILED","message":"这是一张退款截图"}}""" to
                StatusQueryResult.Status(
                    SourceDocumentStatus.Invalid("VALIDATION_FAILED", "这是一张退款截图"),
                ),
            """{"status":"invalid","result":null,"error":{"code":"VALIDATION_FAILED"}}""" to
                StatusQueryResult.Status(SourceDocumentStatus.Invalid("VALIDATION_FAILED", null)),
            """{"status":"anomaly","result":null,"error":{"code":"A01"}}""" to
                StatusQueryResult.Status(SourceDocumentStatus.Anomaly("A01")),
            """{"status":"failed","result":null,"error":{"code":"F01"}}""" to
                StatusQueryResult.Status(SourceDocumentStatus.Failed("F01")),
            """{"status":"cancelled","result":null,"error":null}""" to
                StatusQueryResult.Status(SourceDocumentStatus.Cancelled),
        )

        responses.forEach { (body, expected) ->
            server.enqueue(MockResponse().setResponseCode(200).setBody(body))
            assertEquals(expected, CashierApiClient(httpsClient).query(config(), "doc/id"))
        }
        repeat(responses.size) {
            val request = server.takeRequest()
            assertEquals("GET", request.method)
            assertEquals("/api/v1/source-documents/doc%2Fid", request.path)
            assertEquals("Bearer secret-key", request.getHeader("Authorization"))
        }
    }

    @Test
    fun `maps status query failures and retryability`() = runBlocking {
        listOf(
            401 to StatusQueryResult.Failed(StatusQueryFailure.UNAUTHORIZED, false),
            404 to StatusQueryResult.Failed(StatusQueryFailure.NOT_FOUND, false),
            429 to StatusQueryResult.Failed(StatusQueryFailure.RATE_LIMITED, true, 7_000),
            503 to StatusQueryResult.Failed(StatusQueryFailure.SERVER_ERROR, true),
            422 to StatusQueryResult.Failed(StatusQueryFailure.REJECTED, false),
            200 to StatusQueryResult.Failed(StatusQueryFailure.INVALID_RESPONSE, false),
        ).forEach { (status, expected) ->
            server.enqueue(
                MockResponse()
                    .setResponseCode(status)
                    .setHeader("Retry-After", "7")
                    .setBody("{}"),
            )
            assertEquals(expected, CashierApiClient(httpsClient).query(config(), "a"))
        }
    }

    @Test
    fun `parses completed response with empty entries`() = runBlocking {
        server.enqueue(
            MockResponse().setResponseCode(200)
                .setBody("""{"status":"completed","result":{"title":null,"total":"0.00","totalCurrency":"CNY","entries":[]},"error":null}"""),
        )

        assertEquals(
            StatusQueryResult.Status(SourceDocumentStatus.Completed(emptyList())),
            CashierApiClient(httpsClient).query(config(), "a"),
        )
    }

    @Test
    fun `rejects malformed status responses`() = runBlocking {
        listOf(
            """{}""",
            """{"revisionState":"processing"}""",
            """{"status":"queued"}""",
            """{"status":"completed","result":null}""",
            """{"status":"completed","result":"invalid"}""",
            """{"status":"completed","result":{}}""",
            """{"status":"completed","result":{"entries":"invalid"}}""",
            """{"status":"completed","result":{"entries":[{"amount":"invalid","currency":"CNY","category":"餐饮"}]}}""",
            """{"status":"completed","result":{"entries":[{"amount":10.20,"currency":"CNY","category":"餐饮"}]}}""",
            """{"status":"completed","result":{"entries":[{"amount":"10.20","currency":156,"category":"餐饮"}]}}""",
            """{"status":"completed","result":{"entries":[{"amount":"10.20","currency":"CNY","category":{"name":"餐饮"}}]}}""",
            """{"status":"invalid","error":null}""",
            """{"status":"invalid","error":{"code":""}}""",
            """{"status":"invalid","error":{"code":101}}""",
            """{"status":"anomaly","error":null}""",
            """{"status":"anomaly","error":{"code":""}}""",
            """{"status":"anomaly","error":{"code":101}}""",
            """{"status":"failed","error":{"message":"failed"}}""",
            """{"status":"failed","errorCode":"F01"}""",
        ).forEach { body ->
            server.enqueue(MockResponse().setResponseCode(200).setBody(body))
            assertEquals(
                StatusQueryResult.Failed(StatusQueryFailure.INVALID_RESPONSE, false),
                CashierApiClient(httpsClient).query(config(), "a"),
            )
        }
    }

    @Test
    fun `maps authentication rate limit and server errors`() = runBlocking {
        listOf(
            401 to UploadResult.Failed(UploadFailure.UNAUTHORIZED),
            429 to UploadResult.Failed(UploadFailure.RATE_LIMITED, 7_000),
            503 to UploadResult.Failed(UploadFailure.SERVER_ERROR),
            422 to UploadResult.Failed(UploadFailure.REJECTED),
            413 to UploadResult.Failed(UploadFailure.REJECTED),
        ).forEach { (status, expected) ->
            server.enqueue(MockResponse().setResponseCode(status).setHeader("Retry-After", "7"))
            assertEquals(
                expected,
                CashierApiClient(httpsClient).upload(config(), byteArrayOf(1), IDEMPOTENCY_KEY),
            )
        }
    }

    @Test
    fun `invalid configuration is reported instead of escaping`() = runBlocking {
        val client = CashierApiClient(httpsClient)

        assertEquals(
            UploadResult.Failed(UploadFailure.INVALID_CONFIGURATION),
            client.upload(AppConfig("http://localhost", "key"), byteArrayOf(1), IDEMPOTENCY_KEY),
        )
        assertEquals(
            UploadResult.Failed(UploadFailure.INVALID_CONFIGURATION),
            client.upload(AppConfig("https://localhost:99999", "key"), byteArrayOf(1), IDEMPOTENCY_KEY),
        )
        assertEquals(
            UploadResult.Failed(UploadFailure.INVALID_CONFIGURATION),
            client.upload(AppConfig(server.url("/").toString(), "密钥包含中文"), byteArrayOf(1), IDEMPOTENCY_KEY),
        )
        assertEquals(
            StatusQueryResult.Failed(StatusQueryFailure.INVALID_CONFIGURATION, false),
            client.query(AppConfig("https://localhost:99999", "key"), "a"),
        )
        assertEquals(
            StatusQueryResult.Failed(StatusQueryFailure.INVALID_CONFIGURATION, false),
            client.query(AppConfig(server.url("/").toString(), "key with spaces"), "a"),
        )
        assertEquals(0, server.requestCount)
    }

    @Test
    fun `does not retry a timed out upload`() = runBlocking {
        server.enqueue(MockResponse().setSocketPolicy(SocketPolicy.NO_RESPONSE))
        val shortTimeoutClient = httpsClient.newBuilder()
            .readTimeout(200, TimeUnit.MILLISECONDS)
            .retryOnConnectionFailure(false)
            .build()

        assertEquals(
            UploadResult.Failed(UploadFailure.NETWORK_ERROR),
            CashierApiClient(shortTimeoutClient).upload(config(), byteArrayOf(1), IDEMPOTENCY_KEY),
        )
        assertEquals(1, server.requestCount)
    }

    @Test
    fun `status query times out as retryable network error`() = runBlocking {
        server.enqueue(MockResponse().setSocketPolicy(SocketPolicy.NO_RESPONSE))

        assertEquals(
            StatusQueryResult.Failed(StatusQueryFailure.NETWORK_ERROR, true),
            CashierApiClient(httpsClient, queryTimeoutMillis = 200).query(config(), "a"),
        )
        assertEquals(1, server.requestCount)
    }

    @Test
    fun `cancelling before the response headers cancels the underlying call`() = runBlocking {
        server.enqueue(MockResponse().setSocketPolicy(SocketPolicy.NO_RESPONSE))
        val job = launch(start = CoroutineStart.UNDISPATCHED) {
            CashierApiClient(httpsClient, queryTimeoutMillis = 30_000).query(config(), "a")
        }
        assertTrue(server.takeRequest(2, TimeUnit.SECONDS) != null)

        withTimeout(1_000) {
            job.cancelAndJoin()
        }
    }

    @Test
    fun `cancelling during the response body releases the connection`() = runBlocking {
        val slowBody = """{"status":"completed","result":{"entries":[]},"padding":""}"""
        server.enqueue(
            MockResponse()
                .setResponseCode(200)
                .setBody(slowBody)
                .throttleBody(4_096, 20, TimeUnit.MILLISECONDS),
        )

        val job = launch(start = CoroutineStart.UNDISPATCHED) {
            CashierApiClient(httpsClient, queryTimeoutMillis = 60_000).query(config(), "a")
        }
        assertTrue(server.takeRequest(2, TimeUnit.SECONDS) != null)
        delay(200)

        withTimeout(2_000) {
            job.cancelAndJoin()
        }

        // The cancelled body read must not leak the connection: a following
        // request on the same client still succeeds.
        server.enqueue(
            MockResponse().setResponseCode(200).setBody("""{"status":"cancelled","error":null}"""),
        )
        assertEquals(
            StatusQueryResult.Status(SourceDocumentStatus.Cancelled),
            CashierApiClient(httpsClient).query(config(), "b"),
        )
    }

    @Test
    fun `a pending request never blocks the calling thread`() = runBlocking {
        server.enqueue(MockResponse().setSocketPolicy(SocketPolicy.NO_RESPONSE))
        val caller = kotlinx.coroutines.Dispatchers.IO.limitedParallelism(1)

        var progressedWhileWaiting = false
        val job = launch(caller) {
            // This coroutine shares the single-threaded dispatcher with the
            // request, so it can only run if the request suspends.
            launch {
                delay(100)
                progressedWhileWaiting = true
            }
            CashierApiClient(httpsClient, queryTimeoutMillis = 3_000).query(config(), "a")
        }
        job.join()

        assertTrue("the caller thread must stay free while the request is pending", progressedWhileWaiting)
    }

    private fun config() = AppConfig(
        baseUrl = server.url("/").toString().trimEnd('/'),
        apiKey = "secret-key",
    )

    private companion object {
        const val IDEMPOTENCY_KEY = "11111111-2222-3333-4444-555555555555"
    }
}
